-- Private documentation deadline/expiry reminders using the existing notification/email pipeline.
-- Run after private-legal-progress.sql and private-appointment-reminders.sql.
begin;
create table if not exists public.cb_legal_reminders(id uuid not null unique default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,scope text not null check(scope in ('personal','demo')),project_ref text not null,record_ref text not null,kind text not null check(kind in ('Deadline','Expiry')),days integer not null default 7 check(days in (1,3,7,14,30)),zone text not null,in_app boolean not null default false,email boolean not null default false,revision bigint not null default 1,primary key(user_id,scope,project_ref,record_ref,kind));
create table if not exists public.cb_legal_reminder_writes(user_id uuid not null references auth.users on delete cascade,client uuid not null,payload jsonb not null,response jsonb not null,primary key(user_id,client));
alter table public.cb_legal_reminders enable row level security;alter table public.cb_legal_reminder_writes enable row level security;revoke all on public.cb_legal_reminders,public.cb_legal_reminder_writes from public,anon,authenticated;
create or replace function public.cb_legal_reminder_date(p_user uuid,p_scope text,p_project text,p_ref text,p_kind text,p_zone text) returns date language plpgsql stable security definer set search_path='' as $$
declare r jsonb;p jsonb;d date;source_spec jsonb;progress public.cb_legal_progress;skipped boolean;complete boolean;begin
 p=public.cb_care_owner_record(p_user,p_scope,'projects',p_project);r=public.cb_care_owner_record(p_user,p_scope,'legalRecords',p_ref);
 if p is null or coalesce((p->>'archived')::boolean,false) or coalesce(p->>'archiveStatus','') like 'Archived%' or r is null or r->>'projectId' is distinct from p_project or coalesce(r->>'kind','') not in ('Marriage registration','Identity & supporting documents','Appointments & witnesses','Name & account updates','International documentation') or coalesce((r->>'archived')::boolean,false) then return null;end if;
 if p_kind not in ('Deadline','Expiry') then return null;end if;
 if coalesce(r->>(case when p_kind='Deadline' then 'due' else 'expires' end),'')!~'^\d{4}-\d{2}-\d{2}$' then return null;end if;d=(r->>(case when p_kind='Deadline' then 'due' else 'expires' end))::date;
 if jsonb_typeof(r->'checklist')='array' then
 source_spec=jsonb_build_object('kind',r->>'kind','guide',r->>'guideKey','order',r->'guideOrder','items',(select coalesce(jsonb_agg(jsonb_build_object('id',value->>'id','title',value->>'title') order by ord),'[]') from jsonb_array_elements(r->'checklist') with ordinality a(value,ord)));
 select * into progress from public.cb_legal_progress where user_id=p_user and scope=p_scope and project_ref=p_project and record_ref=p_ref and definition=md5(source_spec::text);end if;
 if progress.user_id is not null then skipped=coalesce((progress.data->>'skipped')::boolean,false);complete=coalesce((progress.data->>'completed')::boolean,false) and public.cb_legal_confirmation_ok(r,(now() at time zone p_zone)::date) and progress.data->'confirmation'=jsonb_build_object('source',coalesce(r->>'source',''),'verified',coalesce(r->>'verified',''));
 else skipped=coalesce(r->'guideSkipped'='true'::jsonb,false) and r->>'kind' in ('Name & account updates','International documentation');complete=r->>'status'='Complete' and public.cb_legal_confirmation_ok(r,(now() at time zone p_zone)::date) and case when jsonb_typeof(r->'checklist')='array' then not exists(select 1 from jsonb_array_elements(r->'checklist') v where v->'done' is distinct from 'true'::jsonb) else false end;end if;
 if skipped or p_kind='Deadline' and coalesce(complete,false) then return null;end if;return d;
exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format then return null;end;$$;
create or replace function public.cb_legal_reminder_current(p_user uuid,p_id uuid,p_token text) returns boolean language plpgsql stable security definer set search_path='' as $$
declare s public.cb_legal_reminders;d date;begin
 select * into s from public.cb_legal_reminders where id=p_id and user_id=p_user;if s.id is null or not(s.in_app or s.email) then return false;end if;
 d=public.cb_legal_reminder_date(s.user_id,s.scope,s.project_ref,s.record_ref,s.kind,s.zone);return coalesce(d is not null and now()>=((d-s.days)+time '09:00') at time zone s.zone and p_token='legal:'||d||':'||s.revision,false);end;$$;
create or replace function public.cb_private_legal_reminders(p_scope text,p_project text,p_ref text,p_kind text,p_zone text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare s public.cb_legal_reminders;r jsonb;d date;z text;begin
 if auth.uid() is null or p_scope is null or p_scope not in ('personal','demo') or p_kind is null or p_kind not in ('Deadline','Expiry') or not exists(select 1 from pg_timezone_names where name=p_zone) then raise exception 'Open your own reminder settings' using errcode='42501';end if;
 select * into s from public.cb_legal_reminders where user_id=auth.uid() and scope=p_scope and project_ref=p_project and record_ref=p_ref and kind=p_kind;r=public.cb_care_owner_record(auth.uid(),p_scope,'legalRecords',p_ref);
 if r->>'projectId' is distinct from p_project and s.id is null then raise exception 'Open your own documentation record first' using errcode='42501';end if;
 z=coalesce(s.zone,p_zone);d=public.cb_legal_reminder_date(auth.uid(),p_scope,p_project,p_ref,p_kind,z);
 return jsonb_build_object('date',d,'ready',d is not null,'past',d<(now() at time zone z)::date,'zone',z,'settings',case when s.id is not null then to_jsonb(s)-'user_id' else null end,'email_available',public.cb_planning_email_ready(),'email_blocked',exists(select 1 from public.cb_planning_preferences p join auth.users u on u.id=p.user_id where p.user_id=auth.uid() and lower(p.suppressed_email)=lower(u.email)),'scheduled',exists(select 1 from pg_extension where extname='pg_cron'));end;$$;
create or replace function public.cb_save_legal_reminders(p_scope text,p_project text,p_ref text,p_kind text,p_date date,p_revision bigint,p_client uuid,p_days integer,p_zone text,p_in_app boolean,p_email boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.cb_legal_reminders;r jsonb;d date;old public.cb_legal_reminder_writes;payload jsonb;result jsonb;begin
 if auth.uid() is null or p_scope is null or p_scope not in ('personal','demo') then raise exception 'Sign in to save reminders' using errcode='42501';end if;
 perform 1 from public.cb_workspace_states where user_id=auth.uid() and workspace='bride' for update;
 if p_kind is null or p_kind not in ('Deadline','Expiry') or p_days is null or p_days not in (1,3,7,14,30) or p_revision is null or p_revision<0 or p_client is null or p_in_app is null or p_email is null or not exists(select 1 from pg_timezone_names where name=p_zone) then raise exception 'Review your reminder settings';end if;
 select * into s from public.cb_legal_reminders where user_id=auth.uid() and scope=p_scope and project_ref=p_project and record_ref=p_ref and kind=p_kind for update;r=public.cb_care_owner_record(auth.uid(),p_scope,'legalRecords',p_ref);
 if r->>'projectId' is distinct from p_project and s.id is null then raise exception 'Open your own documentation record first' using errcode='42501';end if;
 payload=jsonb_build_object('scope',p_scope,'project',p_project,'ref',p_ref,'kind',p_kind,'date',p_date,'revision',p_revision,'days',p_days,'zone',p_zone,'in_app',p_in_app,'email',p_email);
 select * into old from public.cb_legal_reminder_writes where user_id=auth.uid() and client=p_client;if found then if old.payload is distinct from payload then raise exception 'Retry the same reminder settings' using errcode='PT409';end if;return old.response;end if;
 d=public.cb_legal_reminder_date(auth.uid(),p_scope,p_project,p_ref,p_kind,p_zone);
 if p_in_app or p_email then if d is null then raise exception 'Choose an active record with a valid deadline or expiry date';end if;if d is distinct from p_date then raise exception 'This date changed. Reopen the reminders first.' using errcode='PT409';end if;end if;
 if p_email then
 if p_scope='demo' then raise exception 'Email reminders are available in your personal workspace';end if;if d<(now() at time zone p_zone)::date then raise exception 'Choose a current or future date for email reminders';end if;
 if not public.cb_planning_email_ready() then raise exception 'Email reminders are unavailable right now';end if;if not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null) then raise exception 'Verify your email address first';end if;
 if exists(select 1 from public.cb_planning_preferences p join auth.users u on u.id=p.user_id where p.user_id=auth.uid() and lower(p.suppressed_email)=lower(u.email)) then raise exception 'Email is paused for this address after a delivery problem';end if;end if;
 if coalesce(s.revision,0)<>p_revision then raise exception 'Another device updated these reminders. Reopen to review.' using errcode='PT409';end if;
 insert into public.cb_planning_preferences(user_id) values(auth.uid()) on conflict do nothing;
 insert into public.cb_legal_reminders(user_id,scope,project_ref,record_ref,kind,days,zone,in_app,email) values(auth.uid(),p_scope,p_project,p_ref,p_kind,p_days,p_zone,p_in_app,p_email) on conflict(user_id,scope,project_ref,record_ref,kind) do update set days=excluded.days,zone=excluded.zone,in_app=excluded.in_app,email=excluded.email,revision=cb_legal_reminders.revision+1 returning * into s;
 result=to_jsonb(s)-'user_id';insert into public.cb_legal_reminder_writes values(auth.uid(),p_client,payload,result);return result;end;$$;
-- Preserve all existing notification kinds while adding another private, project-less kind.
do $constraint$ declare d text;begin select pg_get_constraintdef(oid) into d from pg_constraint where conrelid='public.cb_planning_notifications'::regclass and conname='cb_planning_notifications_source_kind_check';if strpos(d,'private_legal')=0 then d=replace(d,'''private_care''::text','''private_care''::text, ''private_legal''::text');if strpos(d,'private_legal')=0 then raise exception 'Notification source constraint needs review';end if;alter table public.cb_planning_notifications drop constraint cb_planning_notifications_source_kind_check;execute 'alter table public.cb_planning_notifications add constraint cb_planning_notifications_source_kind_check '||d;end if;end;$constraint$;
alter table public.cb_planning_notifications drop constraint if exists cb_planning_private_project_check;
alter table public.cb_planning_notifications add constraint cb_planning_private_project_check check((source_kind in ('private_care','private_legal') and project_id is null) or (source_kind not in ('private_care','private_legal') and project_id is not null));
do $wrap$ begin
 if to_regprocedure('public.cb_planning_can_view_before_private_legal(uuid,uuid,text,uuid)') is null then alter function public.cb_planning_can_view(uuid,uuid,text,uuid) rename to cb_planning_can_view_before_private_legal;end if;
 if to_regprocedure('public.cb_planning_notice_visible_before_private_legal(uuid,text,uuid,date,text,text)') is null then alter function public.cb_planning_notice_visible(uuid,text,uuid,date,text,text) rename to cb_planning_notice_visible_before_private_legal;end if;
 if to_regprocedure('public.cb_generate_planning_reminders_before_private_legal(uuid)') is null then alter function public.cb_generate_planning_reminders(uuid) rename to cb_generate_planning_reminders_before_private_legal;end if;
 if to_regprocedure('public.cb_care_email_valid_before_private_legal(uuid,uuid)') is null then alter function public.cb_care_email_valid(uuid,uuid) rename to cb_care_email_valid_before_private_legal;end if;
end;$wrap$;
create or replace function public.cb_planning_can_view(p_user uuid,p_project uuid,p_kind text,p_source uuid) returns boolean language sql stable security definer set search_path='' as $$select case when p_kind='private_legal' then exists(select 1 from public.cb_legal_reminders where id=p_source and user_id=p_user) else public.cb_planning_can_view_before_private_legal(p_user,p_project,p_kind,p_source) end$$;
create or replace function public.cb_planning_notice_visible(p_project uuid,p_kind text,p_source uuid,p_date date,p_category text,p_notice_kind text) returns boolean language sql stable security definer set search_path='' as $$select case when p_kind='private_legal' then public.cb_legal_reminder_current(auth.uid(),p_source,p_notice_kind) and exists(select 1 from public.cb_legal_reminders where id=p_source and user_id=auth.uid() and in_app) else public.cb_planning_notice_visible_before_private_legal(p_project,p_kind,p_source,p_date,p_category,p_notice_kind) end$$;
create or replace function public.cb_generate_legal_reminders(p_user uuid default null) returns integer language plpgsql security definer set search_path='' as $$
declare s public.cb_legal_reminders;d date;token text;nid uuid;counted integer=0;begin
 for s in select * from public.cb_legal_reminders where (p_user is null or user_id=p_user) and (in_app or email) loop
 d=public.cb_legal_reminder_date(s.user_id,s.scope,s.project_ref,s.record_ref,s.kind,s.zone);token='legal:'||d||':'||s.revision;if not public.cb_legal_reminder_current(s.user_id,s.id,token) then continue;end if;
 insert into public.cb_planning_notifications(user_id,project_id,category,kind,source_kind,source_id,source_date,title,body,dedupe_key) values(s.user_id,null,'schedule',token,'private_legal',s.id,d,'A private planning date needs your attention','Sign in to review your documentation deadline or expiry date.','private-legal:'||s.id||':'||token) on conflict(user_id,dedupe_key) do nothing;
 select id into nid from public.cb_planning_notifications where user_id=s.user_id and dedupe_key='private-legal:'||s.id||':'||token;
 if s.email and s.scope='personal' and d>=(now() at time zone s.zone)::date then insert into public.cb_planning_email_jobs(user_id,local_day,notice_through,care_notice_id) values(s.user_id,(now() at time zone s.zone)::date,now(),nid) on conflict(care_notice_id) where care_notice_id is not null do nothing;end if;counted=counted+1;
 end loop;return counted;end;$$;
create or replace function public.cb_generate_planning_reminders(p_user uuid default null) returns integer language plpgsql security definer set search_path='' as $$begin return public.cb_generate_planning_reminders_before_private_legal(p_user)+public.cb_generate_legal_reminders(p_user);end;$$;
create or replace function public.cb_care_email_valid(p_user uuid,p_notice uuid) returns boolean language sql stable security definer set search_path='' as $$select case when exists(select 1 from public.cb_planning_notifications where id=p_notice and source_kind='private_legal') then exists(select 1 from public.cb_planning_notifications n join public.cb_legal_reminders s on s.id=n.source_id join auth.users u on u.id=n.user_id left join public.cb_planning_preferences p on p.user_id=u.id where n.id=p_notice and n.user_id=p_user and s.user_id=p_user and s.email and s.scope='personal' and u.email_confirmed_at is not null and u.email is not null and lower(coalesce(p.suppressed_email,''))<>lower(u.email) and public.cb_legal_reminder_current(p_user,s.id,n.kind) and n.source_date>=(now() at time zone s.zone)::date) else public.cb_care_email_valid_before_private_legal(p_user,p_notice) end$$;
create or replace function public.cb_legal_notice_target(p_notice uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare n public.cb_planning_notifications;s public.cb_legal_reminders;begin
 select * into n from public.cb_planning_notifications where id=p_notice and user_id=auth.uid() and source_kind='private_legal';select * into s from public.cb_legal_reminders where id=n.source_id and user_id=auth.uid();if n.id is null or not public.cb_legal_reminder_current(auth.uid(),s.id,n.kind) then raise exception 'This private reminder is no longer current' using errcode='42501';end if;return jsonb_build_object('scope',s.scope,'project',s.project_ref,'record',s.record_ref,'kind',s.kind);end;$$;
drop policy if exists planning_inbox_own on public.cb_planning_notifications;
create policy planning_inbox_own on public.cb_planning_notifications for select to authenticated using(user_id=auth.uid() and public.cb_planning_notice_visible(project_id,source_kind,source_id,source_date,category,kind));
-- Extend the existing sender rather than adding credentials, queues or a second allowance.
do $mailer$ declare body text;private_template text;begin
 body=pg_get_functiondef('public.cb_process_planning_email()'::regprocedure);
 if strpos(body,'public.cb_generate_legal_reminders')=0 then
 body=replace(body,'perform public.cb_generate_care_reminders();','perform public.cb_generate_care_reminders(); perform public.cb_generate_legal_reminders();');
 body=replace(body,'for update of a,s;','for update of a,s;'||chr(10)||'perform 1 from public.cb_legal_reminders s join public.cb_planning_notifications n on n.source_id=s.id where n.id=job.care_notice_id and n.source_kind=''private_legal'' and s.user_id=job.user_id for update of s;');
 private_template=$template$
 if exists(select 1 from public.cb_planning_notifications where id=job.care_notice_id and source_kind='private_legal') then
 text_body='A private planning date needs your attention.'||chr(10)||chr(10)||'Sign in to review it: https://www.cobridey.com/journey.html?legal_notice='||job.care_notice_id||'#legal'||chr(10)||chr(10)||'You enabled this reminder. Manage it inside your private documentation workspace.'||chr(10)||'Cobridey · Your Bridal Journey Companion';
 html='<html lang="en"><body style="margin:0;padding:32px 16px;background:#faf7f5;color:#111;font-family:Arial,sans-serif"><div style="max-width:540px;margin:auto;background:#fff;border-radius:20px;border-top:6px solid #dc5d38;padding:32px"><p style="font-size:26px;font-weight:bold">Cobridey</p><h1 style="font-size:28px">A little clarity for your next step.</h1><p style="font-size:16px;line-height:1.8">A private planning date needs your attention. Sign in to review it.</p><a href="https://www.cobridey.com/journey.html?legal_notice='||job.care_notice_id||'#legal" style="display:inline-block;padding:15px 22px;background:#bf285e;border-radius:12px;color:#fff;text-decoration:none">View my reminder</a><p style="font-size:12px;line-height:1.8;margin-top:28px">You enabled this reminder. Manage it inside your private workspace.<br>Cobridey · Your Bridal Journey Companion</p></div></body></html>';
 body=jsonb_build_object('from','Cobridey <'||settings.sender||'>','to',jsonb_build_array(recipient.email),'subject','Your private Cobridey planning reminder','html',html,'text',text_body);
 else
$template$;
 if strpos(body,'if job.payload is null and job.care_notice_id is not null then')=0 then raise exception 'Private email sender needs review before activation';end if;
 body=replace(body,'if job.payload is null and job.care_notice_id is not null then','if job.payload is null and job.care_notice_id is not null then'||private_template);
 body=replace(body,'elsif job.payload is null then','end if; elsif job.payload is null then');execute body;
 end if;
 body=pg_get_functiondef('public.cb_planning_digest_items(uuid,timestamptz,timestamptz)'::regprocedure);body=replace(body,'n.source_kind<>''private_care''','n.source_kind not in (''private_care'',''private_legal'')');execute body;
end;$mailer$;
revoke all on function public.cb_legal_reminder_date(uuid,text,text,text,text,text),public.cb_legal_reminder_current(uuid,uuid,text),public.cb_generate_legal_reminders(uuid),public.cb_private_legal_reminders(text,text,text,text,text),public.cb_save_legal_reminders(text,text,text,text,date,bigint,uuid,integer,text,boolean,boolean),public.cb_legal_notice_target(uuid),public.cb_planning_can_view(uuid,uuid,text,uuid),public.cb_planning_can_view_before_private_legal(uuid,uuid,text,uuid),public.cb_planning_notice_visible_before_private_legal(uuid,text,uuid,date,text,text),public.cb_generate_planning_reminders_before_private_legal(uuid),public.cb_generate_planning_reminders(uuid),public.cb_care_email_valid_before_private_legal(uuid,uuid),public.cb_care_email_valid(uuid,uuid),public.cb_process_planning_email() from public,anon,authenticated;
grant execute on function public.cb_private_legal_reminders(text,text,text,text,text),public.cb_save_legal_reminders(text,text,text,text,date,bigint,uuid,integer,text,boolean,boolean),public.cb_legal_notice_target(uuid) to authenticated;
revoke all on function public.cb_planning_notice_visible(uuid,text,uuid,date,text,text) from public,anon;grant execute on function public.cb_planning_notice_visible(uuid,text,uuid,date,text,text) to authenticated;
do $refresh$ declare signature text;body text;begin foreach signature in array array['public.cb_queue_planning_notice(uuid,uuid,text,text,text,uuid,date,text,text,text)','public.cb_planning_inbox()','public.cb_read_planning_notifications(uuid,boolean)'] loop body=pg_get_functiondef(to_regprocedure(signature));execute body;end loop;end;$refresh$;
do $cron$ begin if exists(select 1 from pg_extension where extname='pg_cron') then perform cron.schedule('cb-private-legal-reminders','*/5 * * * *','select public.cb_generate_legal_reminders();');end if;end;$cron$;
notify pgrst,'reload schema';commit;
